'use strict';
const fs=require('node:fs'),crypto=require('node:crypto'),assert=require('node:assert/strict');
const base='releases/v390',root='releases/v391',read=(p,n)=>fs.readFileSync(p+'/'+n,'utf8'),hash=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const m=JSON.parse(read(root,'manifest.json')),p=JSON.parse(read(root,'provenance.json'));
assert.equal(m.release,'v391');assert.equal(m.base_release,'v390');
for(const[n,h]of Object.entries(m.files))assert.equal(hash(root+'/'+n),h,n);
for(const[n,h]of Object.entries(m.protected))assert.equal(hash(n),h,n);
for(const[n,h]of Object.entries(p.protected_base_files))assert.equal(hash(base+'/'+n),h,n);
assert.deepEqual(fs.readdirSync(root).sort(),fs.readdirSync(base).sort());
assert.deepEqual(fs.readdirSync(root).filter(n=>hash(root+'/'+n)!==hash(base+'/'+n)).sort(),[...p.runtime_changes,'manifest.json','provenance.json'].sort());
const name='lts-v226-card-composition.js',old=read(base,name),next=read(root,name);
assert.equal(read(root,'lts-v384-startup-2.js'),read(base,'lts-v384-startup-2.js').replace(old,next));
const financial=s=>s.slice(s.indexOf('    function compositionEvidence('),s.indexOf('    function detailBody('));assert.equal(financial(next),financial(old));
const payments=s=>s.slice(s.indexOf('function documentaryPaymentNote('),s.indexOf('    const v233Formatters'));assert.equal(payments(next),payments(old));
const mutations=s=>s.slice(s.indexOf("          dialog.querySelectorAll('[data-v226-classify]')"),s.indexOf('        };draw();'));assert.equal(mutations(next),mutations(old));
assert.deepEqual([...next.matchAll(/(?:S\.rpc|await rpc)\('([^']+)'/g)].map(x=>x[1]),[...old.matchAll(/(?:S\.rpc|await rpc)\('([^']+)'/g)].map(x=>x[1]));
assert(next.includes('Vencimento estimado: '));assert(next.includes('Confira a futura fatura antes de pagar.'));
assert.equal(hash(root+'/lts-property-reconciliation-model.js'),hash(base+'/lts-property-reconciliation-model.js'),'closed property comparison unchanged');
const live=process.env.LTS_MOBILE_RELEASE||'v391';assert.deepEqual(JSON.parse(fs.readFileSync('mobile/current.json')),{release:live,entry:'../releases/'+live+'/app.html'});
console.log(JSON.stringify({pass:true,release:'v391',money_and_payment_code_exact:true,mutation_capabilities_exact:true,previous_releases_exact:true,missing_dates_only:true}));
